+
+      .hero {
+        margin-bottom: 24px;
+      }
+
+      .eyebrow {
+        display: inline-flex;
+        align-items: center;
+        gap: 8px;
+        padding: 8px 14px;
+        border-radius: 999px;
+        background: var(--accent-soft);
+        color: #a1481e;
+        font-size: 0.9rem;
+        font-weight: 700;
+        letter-spacing: 0.02em;
+        margin-bottom: 16px;
+      }
+
+      h1 {
+        margin: 0 0 12px;
+        font-size: clamp(2.3rem, 5vw, 4.2rem);
+        line-height: 1.02;
+        letter-spacing: -0.05em;
+      }
+
+      .subtitle {
+        margin: 0;
+        max-width: 62ch;
+        color: var(--muted);
+        font-size: 1.05rem;
+        line-height: 1.7;
+      }
+
+      .faq {
+        margin-top: 32px;
+        display: grid;
+        gap: 16px;
+      }
+
+      .example {
+        background: var(--surface);
+        border: 1px solid var(--surface-border);
+        border-radius: var(--radius);
+        box-shadow: var(--shadow);
+        backdrop-filter: blur(12px);
+        overflow: hidden;
+      }
+
+      .question {
+        width: 100%;
+        border: 0;
+        background: transparent;
+        color: inherit;
+        display: flex;
+        align-items: center;
+        justify-content: space-between;
+        gap: 16px;
+        padding: 22px 24px;
+        text-align: left;
+        cursor: pointer;
+        font: inherit;
+      }
+
+      .question:focus-visible {
+        outline: 3px solid rgba(255, 138, 76, 0.35);
+        outline-offset: -3px;
+      }
+
+      .question-text {
+        margin: 0;
+        font-size: 1.08rem;
+        font-weight: 700;
+        line-height: 1.45;
+      }
+
+      .icon {
+        flex: 0 0 auto;
+        width: 38px;
+        height: 38px;
+        border-radius: 50%;
+        display: grid;
+        place-items: center;
+        background: #f2f5fa;
+        color: var(--accent);
+        font-size: 1.3rem;
+        font-weight: 700;
+        transition: transform 0.22s ease, background 0.22s ease;
+      }
+
+      .details {
+        display: none;
+        padding: 0 24px 22px;
+        color: var(--muted);
+        line-height: 1.8;
+      }
+
+      .example.is-open .details {
+        display: block;
+      }
+
+      .example.is-open .icon {
+        transform: rotate(45deg);
+        background: #ffe0d0;
+      }
+
+      @media (max-width: 640px) {
+        .page {
+          width: min(100% - 20px, 960px);
+          padding: 28px 0 40px;
+        }
+
+        .question {
+          padding: 18px 18px;
+        }
+
+        .details {
+          padding: 0 18px 18px;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <main class="page">
+      <section class="hero" aria-labelledby="faq-title">
+        <div class="eyebrow">Cat FAQ</div>
+        <h1 id="faq-title">Everything you wanted to know about cats</h1>
+        <p class="subtitle">
+          A simple, modern FAQ with expandable answers for quick scanning and easy reading.
+        </p>
+      </section>
+
+      <section class="faq" aria-label="Frequently asked questions">
+        <div class="example">
+          <button class="question" type="button" aria-expanded="false">
+            <p class="question-text">Why do cats purr?</p>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details">
+            Cats purr for comfort, communication, and sometimes self-soothing. It usually means
+            they feel relaxed, though context matters.
+          </div>
+        </div>
+
+        <div class="example">
+          <button class="question" type="button" aria-expanded="false">
+            <p class="question-text">How much sleep do cats need?</p>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details">
+            Most cats sleep between 12 and 16 hours a day, and kittens or older cats may sleep
+            even more.
+          </div>
+        </div>
+
+        <div class="example">
+          <button class="question" type="button" aria-expanded="false">
+            <p class="question-text">Why do cats knead blankets?</p>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details">
+            Kneading is a comforting instinct from kittenhood. Adult cats often do it when they
+            feel safe, content, or bonded with their favorite person.
+          </div>
+        </div>
+
+        <div class="example">
+          <button class="question" type="button" aria-expanded="false">
+            <p class="question-text">Do indoor cats still need enrichment?</p>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details">
+            Yes. Scratching posts, climbing spots, puzzle feeders, and daily play help cats stay
+            healthy, active, and mentally engaged.
+          </div>
+        </div>
+      </section>
+    </main>
+
+    <script>
+      document.querySelectorAll(".example").forEach((example) => {
+        const button = example.querySelector(".question");
+
+        button.addEventListener("click", () => {
+          const open = example.classList.toggle("is-open");
+          button.setAttribute("aria-expanded", String(open));
+        });
+      });
+    </script>
+  </body>
+</html>
*** End Patch
